arguments.file_text:
@page "/chat"
@layout ChatLayout
@rendermode InteractiveServer
@using sv_b4bb52378c1842c2aec703375e35a7ae.Services
@inject IChatService ChatService
@inject IJSRuntime JS

<PageTitle>Team Chat</PageTitle>

<div class="chat-app">
    @* ───── Left Sidebar: Channel List ───── *@
    <aside class="channel-sidebar">
        <div class="sidebar-header">
            <h3>Channels</h3>
        </div>
        <ul class="channel-list">
            @if (_channels is not null)
            {
                @foreach (var ch in _channels)
                {
                    <li class="channel-item @(ch.Id == _activeChannelId ? "active" : "")"
                        @onclick="() => SelectChannelAsync(ch)">
                        <div class="channel-name"># @ch.Name</div>
                        <div class="channel-desc">@TruncateDescription(ch.Description)</div>
                        @if (ch.UnreadCount > 0)
                        {
                            <span class="unread-badge">@ch.UnreadCount</span>
                        }
                    </li>
                }
            }
        </ul>
    </aside>

    @* ───── Main Message Area ───── *@
    <section class="message-area @(_threadOpen ? "" : "expanded")">
        @if (_activeChannel is not null)
        {
            <div class="message-header">
                <h2># @_activeChannel.Name</h2>
                <span class="header-desc">@_activeChannel.Description</span>
            </div>

            <div class="message-list" @ref="_messageListRef" @onscroll="OnMessageListScroll">
                @if (_loadingOlder)
                {
                    <div class="loading-indicator">Loading older messages…</div>
                }
                @if (_messages is not null)
                {
                    @foreach (var msg in _messages)
                    {
                        <div class="message-row" @onmouseover="() => _hoveredMessageId = msg.Id"
                             @onmouseout="() => { if (_hoveredMessageId == msg.Id) _hoveredMessageId = null; }">
                            <div class="message-bubble">
                                <div class="message-meta">
                                    <span class="msg-author">@msg.Author</span>
                                    <span class="msg-time">@FormatRelativeTime(msg.SentAt)</span>
                                </div>
                                <div class="msg-content">@msg.Content</div>

                                @if (msg.Reactions.Count > 0)
                                {
                                    <div class="reaction-row">
                                        @foreach (var r in msg.Reactions)
                                        {
                                            <span class="reaction-badge" title="@string.Join(", ", r.Users)">
                                                @r.Emoji @r.Users.Count
                                            </span>
                                        }
                                    </div>
                                }

                                @{
                                    var thread = _threadSummaries?.FirstOrDefault(t => t.RootMessageId == msg.Id);
                                }
                                @if (thread is not null)
                                {
                                    <button class="thread-link" @onclick="() => OpenThreadAsync(msg)"
                                            @onclick:stopPropagation>
                                        @thread.ReplyCount @(thread.ReplyCount == 1 ? "reply" : "replies")
                                    </button>
                                }
                            </div>

                            @if (_hoveredMessageId == msg.Id)
                            {
                                <div class="message-actions">
                                    <button class="action-btn" title="Reply in thread"
                                            @onclick="() => OpenThreadAsync(msg)">💬 Reply</button>
                                    <div class="emoji-picker-wrapper">
                                        <button class="action-btn" title="Add reaction"
                                                @onclick="() => ToggleEmojiPicker(msg.Id)">😀 React</button>
                                        @if (_emojiPickerMessageId == msg.Id)
                                        {
                                            <div class="emoji-picker">
                                                @foreach (var emoji in _commonEmojis)
                                                {
                                                    <button class="emoji-option"
                                                            @onclick="() => AddReactionAsync(msg.Id, emoji)"
                                                            @onclick:stopPropagation>
                                                        @emoji
                                                    </button>
                                                }
                                            </div>
                                        }
                                    </div>
                                </div>
                            }
                        </div>
                    }
                }
            </div>

            <div class="message-input-area">
                <textarea class="message-textarea" @bind="_newMessageText" @bind:event="oninput"
                          placeholder="Type a message…"
                          @onkeydown="OnMessageKeyDown"></textarea>
                <button class="send-btn" @onclick="SendMessageAsync" disabled="@string.IsNullOrWhiteSpace(_newMessageText)">
                    Send
                </button>
            </div>
        }
        else
        {
            <div class="no-channel-selected">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </section>

    @* ───── Right Panel: Thread View ───── *@
    @if (_threadOpen && _threadRootMessage is not null)
    {
        <aside class="thread-panel">
            <div class="thread-header">
                <h3>Thread</h3>
                <button class="close-thread-btn" @onclick="CloseThread" title="Close thread">✕</button>
            </div>

            <div class="thread-root-quote">
                <div class="message-meta">
                    <span class="msg-author">@_threadRootMessage.Author</span>
                    <span class="msg-time">@FormatRelativeTime(_threadRootMessage.SentAt)</span>
                </div>
                <div class="msg-content">@_threadRootMessage.Content</div>
            </div>

            <div class="thread-replies">
                @if (_threadMessages is not null)
                {
                    @foreach (var reply in _threadMessages)
                    {
                        <div class="message-bubble thread-reply">
                            <div class="message-meta">
                                <span class="msg-author">@reply.Author</span>
                                <span class="msg-time">@FormatRelativeTime(reply.SentAt)</span>
                            </div>
                            <div class="msg-content">@reply.Content</div>
                            @if (reply.Reactions.Count > 0)
                            {
                                <div class="reaction-row">
                                    @foreach (var r in reply.Reactions)
                                    {
                                        <span class="reaction-badge" title="@string.Join(", ", r.Users)">
                                            @r.Emoji @r.Users.Count
                                        </span>
                                    }
                                </div>
                            }
                        </div>
                    }
                }
            </div>

            <div class="message-input-area">
                <textarea class="message-textarea" @bind="_threadReplyText" @bind:event="oninput"
                          placeholder="Reply in thread…"
                          @onkeydown="OnThreadReplyKeyDown"></textarea>
                <button class="send-btn" @onclick="SendThreadReplyAsync"
                        disabled="@string.IsNullOrWhiteSpace(_threadReplyText)">
                    Reply
                </button>
            </div>
        </aside>
    }
</div>

@code {
    private const int PageSize = 30;

    private List<Channel>? _channels;
    private int _activeChannelId;
    private Channel? _activeChannel;

    private List<Message>? _messages;
    private List<ThreadSummary>? _threadSummaries;
    private int _messageSkip;
    private bool _loadingOlder;
    private bool _allOlderLoaded;

    private bool _threadOpen;
    private Message? _threadRootMessage;
    private List<Message>? _threadMessages;

    private string _newMessageText = "";
    private string _threadReplyText = "";

    private int? _hoveredMessageId;
    private int? _emojiPickerMessageId;

    private ElementReference _messageListRef;

    private readonly string[] _commonEmojis = ["👍", "❤️", "😂", "🎉", "🚀", "👀"];

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannelAsync(_channels[0]);
        }
    }

    // ── Channel selection ──

    private async Task SelectChannelAsync(Channel channel)
    {
        if (channel.Id == _activeChannelId) return;

        _activeChannelId = channel.Id;
        _activeChannel = channel;
        _messageSkip = 0;
        _allOlderLoaded = false;
        _messages = null;
        _threadSummaries = null;

        CloseThread();

        var msgs = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        _messages = msgs;
        _messageSkip = msgs.Count;

        await BuildThreadSummariesAsync();
        await ChatService.MarkChannelReadAsync(channel.Id);
        await RefreshChannelUnread(channel);
    }

    private async Task RefreshChannelUnread(Channel channel)
    {
        _channels = await ChatService.GetChannelsAsync();
        _activeChannel = _channels.FirstOrDefault(c => c.Id == channel.Id) ?? _activeChannel;
    }

    // ── Pagination ──

    private async Task OnMessageListScroll()
    {
        if (_loadingOlder || _allOlderLoaded || _messages is null) return;

        var scrollTop = await JS.InvokeAsync<double>("eval", $"document.querySelector('.message-list')?.scrollTop ?? 1");
        if (scrollTop > 50) return;

        _loadingOlder = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(_activeChannelId, _messageSkip, PageSize);
        if (older.Count == 0)
        {
            _allOlderLoaded = true;
        }
        else
        {
            _messages.InsertRange(0, older);
            _messageSkip += older.Count;
            await BuildThreadSummariesAsync();
        }

        _loadingOlder = false;
    }

    // ── Sending messages ──

    private async Task SendMessageAsync()
    {
        if (string.IsNullOrWhiteSpace(_newMessageText)) return;

        var msg = await ChatService.SendMessageAsync(_activeChannelId, _newMessageText.Trim(), null);
        _messages ??= new();
        _messages.Add(msg);
        _messageSkip++;
        _newMessageText = "";

        await ScrollToBottom();
    }

    private async Task OnMessageKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await SendMessageAsync();
        }
    }

    // ── Thread ──

    private async Task OpenThreadAsync(Message rootMessage)
    {
        _threadRootMessage = rootMessage;
        _threadMessages = await ChatService.GetThreadAsync(rootMessage.Id);
        _threadOpen = true;
        _emojiPickerMessageId = null;
    }

    private void CloseThread()
    {
        _threadOpen = false;
        _threadRootMessage = null;
        _threadMessages = null;
        _threadReplyText = "";
    }

    private async Task SendThreadReplyAsync()
    {
        if (string.IsNullOrWhiteSpace(_threadReplyText) || _threadRootMessage is null) return;

        var reply = await ChatService.SendMessageAsync(_activeChannelId, _threadReplyText.Trim(), _threadRootMessage.Id);
        _threadMessages ??= new();
        _threadMessages.Add(reply);
        _threadReplyText = "";

        await BuildThreadSummariesAsync();
    }

    private async Task OnThreadReplyKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await SendThreadReplyAsync();
        }
    }

    // ── Reactions ──

    private void ToggleEmojiPicker(int messageId)
    {
        _emojiPickerMessageId = _emojiPickerMessageId == messageId ? null : messageId;
    }

    private async Task AddReactionAsync(int messageId, string emoji)
    {
        await ChatService.AddReactionAsync(messageId, emoji);
        _emojiPickerMessageId = null;

        // Refresh messages to show updated reactions
        if (_messages is not null)
        {
            var refreshed = await ChatService.GetMessagesAsync(_activeChannelId, 0, _messageSkip);
            _messages = refreshed;
        }

        // Also refresh thread if open
        if (_threadOpen && _threadRootMessage is not null)
        {
            _threadMessages = await ChatService.GetThreadAsync(_threadRootMessage.Id);
        }
    }

    // ── Thread summaries ──

    private async Task BuildThreadSummariesAsync()
    {
        if (_messages is null) return;

        var summaries = new List<ThreadSummary>();
        var rootIds = _messages.Where(m => m.ReplyToId is null).Select(m => m.Id).ToHashSet();

        foreach (var rootId in rootIds)
        {
            var thread = await ChatService.GetThreadAsync(rootId);
            if (thread.Count > 0)
            {
                summaries.Add(new ThreadSummary(rootId, thread.Count, thread.Max(t => t.SentAt)));
            }
        }

        _threadSummaries = summaries;
    }

    // ── Helpers ──

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt.ToUniversalTime();
        return diff.TotalSeconds switch
        {
            < 60 => "just now",
            < 3600 => $"{(int)diff.TotalMinutes} min ago",
            < 86400 => $"{(int)diff.TotalHours}h ago",
            < 604800 => $"{(int)diff.TotalDays}d ago",
            _ => sentAt.ToString("MMM d, yyyy")
        };
    }

    private static string TruncateDescription(string desc)
    {
        return desc.Length > 40 ? desc[..37] + "…" : desc;
    }

    private async Task ScrollToBottom()
    {
        await JS.InvokeVoidAsync("eval",
            "setTimeout(() => { let el = document.querySelector('.message-list'); if(el) el.scrollTop = el.scrollHeight; }, 50)");
    }
}

