    private readonly string[] _commonEmojis = ["👍", "❤️", "😂", "🎉", "🚀", "👀"];

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannelAsync(_channels[0]);
        }
    }

    // ── Channel selection ──

    private async Task SelectChannelAsync(Channel channel)
    {
        if (channel.Id == _activeChannelId) return;

        _activeChannelId = channel.Id;
        _activeChannel = channel;
        _messageSkip = 0;
        _allOlderLoaded = false;
        _messages = null;
        _threadSummaries = null;

        CloseThread();

        var msgs = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        _messages = msgs;
        _messageSkip = msgs.Count;

        await BuildThreadSummariesAsync();
        await ChatService.MarkChannelReadAsync(channel.Id);
        await RefreshChannelUnread(channel);
    }

    private async Task RefreshChannelUnread(Channel channel)
    {
        _channels = await ChatService.GetChannelsAsync();
        _activeChannel = _channels.FirstOrDefault(c => c.Id == channel.Id) ?? _activeChannel;
    }

    // ── Pagination ──

    private async Task OnMessageListScroll()
    {
        if (_loadingOlder || _allOlderLoaded || _messages is null) return;

        var scrollTop = await JS.InvokeAsync<double>("eval", $"document.querySelector('.message-list')?.scrollTop ?? 1");
        if (scrollTop > 50) return;

        _loadingOlder = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(_activeChannelId, _messageSkip, PageSize);
        if (older.Count == 0)
        {
            _allOlderLoaded = true;
        }
        else
        {
            _messages.InsertRange(0, older);
            _messageSkip += older.Count;
            await BuildThreadSummariesAsync();
        }

        _loadingOlder = false;
    }

    // ── Sending messages ──

    private async Task SendMessageAsync()
    {
        if (string.IsNullOrWhiteSpace(_newMessageText)) return;

        var msg = await ChatService.SendMessageAsync(_activeChannelId, _newMessageText.Trim(), null);
        _messages ??= new();
        _messages.Add(msg);
        _messageSkip++;
        _newMessageText = "";

        await ScrollToBottom();
    }

    private async Task OnMessageKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await SendMessageAsync();
        }
    }

    // ── Thread ──

    private async Task OpenThreadAsync(Message rootMessage)
    {
        _threadRootMessage = rootMessage;
        _threadMessages = await ChatService.GetThreadAsync(rootMessage.Id);
        _threadOpen = true;
        _emojiPickerMessageId = null;
    }

    private void CloseThread()
    {
        _threadOpen = false;
        _threadRootMessage = null;
        _threadMessages = null;
        _threadReplyText = "";
    }

    private async Task SendThreadReplyAsync()
    {
        if (string.IsNullOrWhiteSpace(_threadReplyText) || _threadRootMessage is null) return;

        var reply = await ChatService.SendMessageAsync(_activeChannelId, _threadReplyText.Trim(), _threadRootMessage.Id);
